-- =============================================================================
-- SEED PAQUETE_FECHAS: CALENDARIO DE SALIDAS REALES Y ESTACIONALES (2026 - 2027)
-- Evaluado según duración de paquete, estacionalidad biológica y eventos únicos
-- =============================================================================

ON CONFLICT (paquete_id, fecha_inicio, fecha_fin) DO UPDATE SET
  cupos_totales = EXCLUDED.cupos_totales,
  cupos_disponibles = EXCLUDED.cupos_disponibles,
  precio_salida = EXCLUDED.precio_salida,
  is_active = EXCLUDED.is_active;
